def calculate_average(numbers: list[float]) -> float:
    """Calculate the arithmetic mean of a sequence of numbers."""
    from fractions import Fraction
    import math

    if not isinstance(numbers, (list, tuple)):
        raise TypeError("Input must be a list or tuple")

    if not numbers:
        raise ValueError("Input cannot be empty")

    total = Fraction(0)

    for number in numbers:
        if isinstance(number, bool) or not isinstance(number, (int, float)):
            raise TypeError("All elements must be integers or floats")

        if isinstance(number, float) and not math.isfinite(number):
            raise ValueError("All float elements must be finite")

        total += Fraction(number)

    try:
        result = float(total / len(numbers))
    except OverflowError as error:
        raise ValueError("Result is outside the representable float range") from error

    if not math.isfinite(result):
        raise ValueError("Result is outside the representable float range")

    return result
